// Extract chat IDs from Microsoft Graph response
const chats = $input.item.json.value || [];
const now = new Date();
const thirtyMinAgo = new Date(now.getTime() - 30 * 60 * 1000);

const recentChats = chats.filter(chat => {
  if (!chat.lastMessagePreview) return false;
  const lastMsgTime = new Date(chat.lastMessagePreview.createdDateTime);
  return lastMsgTime > thirtyMinAgo;
});

if (recentChats.length === 0) {
  return [{ json: { skip: true, reason: 'No recent chats in last 30 min' } }];
}

return recentChats.map(chat => ({
  json: {
    chatId: chat.id,
    chatType: chat.chatType,
    topic: chat.topic || 'Direct Message',
    lastMessageTime: chat.lastMessagePreview?.createdDateTime,
    skip: false
  }
}));

// Extract and filter Teams messages for vessel-related content
const messages = $input.item.json.value || [];
const now = new Date();
const thirtyMinAgo = new Date(now.getTime() - 30 * 60 * 1000);

// Vessel keywords to detect relevant messages
const vesselKeywords = ['mv ', 'm/v', 'dwt', 'dwat', 'vessel', 'open', 'ppt', 'prompt',
  'built', 'blt', 'flag', 'crane', 'gear', 'grt', 'nrt', 'loa', 'vlsfo',
  'supramax', 'ultramax', 'panamax', 'handymax', 'handysize', 'kamsarmax',
  'capesize', 'bulker', 'tonnage', 'employment'];

const results = [];

for (const msg of messages) {
  const createdTime = new Date(msg.createdDateTime);
  if (createdTime < thirtyMinAgo) continue;

  // Get message text - Teams messages come as HTML
  let text = msg.body?.content || '';
  // Strip HTML tags
  text = text.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

  if (text.length < 20) continue;

  // Check if message contains vessel-related keywords
  const lowerText = text.toLowerCase();
  const matchCount = vesselKeywords.filter(kw => lowerText.includes(kw)).length;

  if (matchCount >= 2) {
    results.push({
      json: {
        message_text: text,
        sender_name: msg.from?.user?.displayName || 'Unknown',
        sender_email: msg.from?.user?.id || '',
        timestamp: msg.createdDateTime,
        message_id: msg.id,
        source: 'teams',
        skip: false
      }
    });
  }
}

if (results.length === 0) {
  return [{ json: { skip: true, reason: 'No vessel-related messages found' } }];
}

return results;

// Parse and clean the Gemini AI response
const item = $input.item;
let jsonString = '';

if (item.json.text) {
  jsonString = item.json.text;
} else if (item.json.content && item.json.content.parts) {
  jsonString = item.json.content.parts[0].text;
} else if (item.json.output) {
  jsonString = item.json.output;
} else {
  jsonString = JSON.stringify(item.json);
}

jsonString = jsonString.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/, '')
  .trim();

try {
  const parsed = JSON.parse(jsonString);
  if (Array.isArray(parsed)) {
    return { json: { is_relevant: true, vessels: parsed } };
  }
  if (parsed.vessel_name) {
    return { json: { is_relevant: true, vessels: [parsed] } };
  }
  return { json: parsed };
} catch (error) {
  return { json: { is_relevant: false, vessels: [], error: 'JSON parse failed: ' + error.message } };
}

// Split vessels array into individual items with source metadata
const vessels = $input.item.json.vessels || [];
const senderName = $('Extract Vessel Messages').item.json.sender_name || 'Unknown';
const messageId = $('Extract Vessel Messages').item.json.message_id || '';
const timestamp = $('Extract Vessel Messages').item.json.timestamp || new Date().toISOString();

const results = [];

for (const vessel of vessels) {
  vessel.source = 'teams';
  vessel.source_identifier = `teams-${messageId}`;
  vessel.last_seen_at = timestamp;
  vessel.first_seen_at = timestamp;

  if (!vessel.owner_manager) {
    vessel.owner_manager = senderName;
  }

  if (vessel.vessel_name && !vessel.vessel_name.toUpperCase().startsWith('MV ')) {
    vessel.vessel_name = 'MV ' + vessel.vessel_name;
  }
  if (vessel.vessel_name) {
    vessel.vessel_name = vessel.vessel_name.toUpperCase();
  }

  if (Array.isArray(vessel.last_5_cargoes)) {
    vessel.last_5_cargoes = vessel.last_5_cargoes.join(', ');
  }
  if (Array.isArray(vessel.special_features)) {
    vessel.special_features = vessel.special_features.join(', ');
  }

  results.push({ json: vessel });
}

return results;
